INSERT INTO `recetas` (`id`, `id_usuario`, `titulo`, `descripcion`, `imagen`, `contenido`, `favorito`, `puntuacion`) VALUES
(1, 1, 'Cereal', 'Cereal con leche', , '\r\nIngredientes y utensilios\r\n\r\n• 1 taza de tu cereal favorito\r\n• 1 taza de leche (fría, tibia o caliente, según prefieras)\r\n• Un plato hondo o tazón\r\n• Una cuchara\r\n• Opcional: fruta en rebanadas (como plátano o fresas).\r\n\r\n\r\nPasos de preparación\r\n\r\n1. Sirve el cereal: Coloca la cantidad deseada de cereal (aproximadamente una taza) en el fondo del plato hondo.\r\n2. Añade extras (opcional): Si te gusta, agrega rebanadas de fruta, un poco de canela o miel por encima.\r\n3. Vierte la leche: Agrega la leche con cuidado sobre el cereal hasta cubrirlo casi por completo o según qué tan mojado te guste.\r\n4. Disfruta al instante: Come rápido con la cuchara para mantener la textura crujiente del cereal antes de que se ablande', 0, 5);
INSERT INTO `recetas` (`id`, `id_usuario`, `titulo`, `descripcion`, `imagen`, `contenido`, `favorito`, `puntuacion`) VALUES
(2, 1, 'Arroz', 'Arroz blanco', , '\r\nIngredientes básicos\r\n\r\n• 1 taza de arroz de grano largo\r\n• 2 tazas de agua o caldo (de pollo o verduras)\r\n• 1 cucharada de aceite vegetal o mantequilla\r\n• 1/4 de cebolla blanca pequeña\r\n• 1 o 2 dientes de ajo\r\n• Sal al gusto (generalmente 1 a 2 cucharaditas)\r\n\r\n1. Lavar el arroz (opcional pero recomendado): Enjuaga el arroz con agua fría un par de veces para quitar el exceso de almidón y evitar que se pegue. Escúrrelo muy bien.\r\n2. Sofríer o tostar: En una olla o sartén con tapa, calienta el aceite o la mantequilla a fuego medio. Añade el arroz y dóralo ligeramente durante 2 o 3 minutos hasta que los granos se vean un poco opacos o translúcidos\r\n3. Agregar sabor: Incorpora el ajo y la cebolla (puedes picarlos finamente o licuarlos con el agua). Sofríe un minuto más sin que se quemen. \r\n4. Incorporar el líquido: Vierte las 2 tazas de agua o caldo caliente y agrega la sal. Revuelve una sola vez para integrar. \r\n5. Cocinar: Espera a que hierva, baja el fuego al mínimo, tapa la olla y déjalo cocinar durante 15 minutos. No levantes la tapa ni lo revuelvas durante este tiempo. \r\n6. Reposar: Apaga el fuego y deja reposar el arroz tapado durante 5 minutos más para que termine de absorber el vapor. \r\n7. Esponjar: Destápalo y usa un tenedor (nunca una cuchara) para separar los granos con suavidad\r\n', 1, 4);

